// src/components/SuccessProjects/SuccessProjects.js
import React from 'react';
import styles from './SuccessProjects.module.css';

const SuccessProjects = () => {
    const projects = [
        {
            title: 'Plataforma de IA para E-commerce',
            client: 'Varejo Digital',
            description: 'Sistema de recomendação baseado em ML que aumentou as vendas em 45% através de personalização avançada.',
            technologies: ['Python', 'TensorFlow', 'AWS SageMaker', 'Redis'],
            results: [
                '+45% em conversões',
                '2M+ usuários ativos',
                '99.9% uptime'
            ]
        },
        {
            title: 'ChatBot Inteligente com LLM',
            client: 'Fintech Brasileira',
            description: 'Assistente virtual integrado com GPT-4 para atendimento ao cliente, reduzindo tempo de resposta em 80%.',
            technologies: ['Node.js', 'OpenAI API', 'PostgreSQL', 'Docker'],
            results: [
                '-80% tempo de resposta',
                '95% satisfação',
                '200k+ interações/mês'
            ]
        },
        {
            title: 'Pipeline MLOps em Cloud',
            client: 'Healthtech',
            description: 'Arquitetura completa de MLOps para diagnóstico médico assistido por IA com certificação HIPAA.',
            technologies: ['Kubernetes', 'MLflow', 'Azure ML', 'Terraform'],
            results: [
                '10x deploy speed',
                'ISO 27001 compliant',
                '5ms latência média'
            ]
        }
    ];

    return (
        <section id="projects" className={styles.section}>
            <div className={styles.container}>
                <div className={styles.header}>
                    <h2 className={styles.title}>
                        PROJETOS DE <span className={styles.highlight}>SUCESSO</span>
                    </h2>
                    <p className={styles.subtitle}>
                        Cases reais de transformação digital com resultados mensuráveis
                    </p>
                </div>

                <div className={styles.projectsGrid}>
                    {projects.map((project, index) => (
                        <div key={index} className={styles.projectCard}>
                            <div className={styles.cardHeader}>
                                <span className={styles.projectNumber}>0{index + 1}</span>
                                <span className={styles.client}>{project.client}</span>
                            </div>

                            <h3 className={styles.projectTitle}>{project.title}</h3>
                            <p className={styles.projectDescription}>{project.description}</p>

                            <div className={styles.technologies}>
                                {project.technologies.map((tech, idx) => (
                                    <span key={idx} className={styles.techBadge}>{tech}</span>
                                ))}
                            </div>

                            <div className={styles.results}>
                                <h4 className={styles.resultsTitle}>Resultados:</h4>
                                <ul className={styles.resultsList}>
                                    {project.results.map((result, idx) => (
                                        <li key={idx} className={styles.resultItem}>{result}</li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default SuccessProjects;
